mapper.delete:
delete from ${attSignTable}
where signdate >= #{winFromDate} and signdate <= #{winToDate}
  and signfrom in
  #{src}

      and userid in
      #{uid}

mapper.select:
select count(1) from ${attSignTable}
where userid = #{oaUserId} and signdate = #{signDate} and signtime = #{signTime}
  and signtype = #{signType} and signfrom in
  #{src}

select top 1 cast(id as varchar(64)) from ${attSignTable}
where userid = #{oaUserId} and signdate = #{signDate} and signtime = #{signTime}
  and signtype = #{signType}
order by id

select top (#{limit})
       cast(id as varchar(64)) as sign_id,
       cast(userid as int) as oa_user_id,
       signdate as sign_date,
       signtime as sign_time,
       isnull(signdate, '') + ' ' + isnull(signtime, '') as sign_datetime,
       cast(signtype as int) as sign_type,
       isnull(signfrom, '') as sign_from
from ${attSignTable}
where signdate >= #{fromDate} and signdate <= #{toDate}

    and userid in
    #{uid}


    and signtype in
    #{st}


    and (signfrom is null or signfrom = '' or signfrom not in
    #{src}
    )

order by signdate, signtime, userid
